export const getUpdateClientProfileUrl = () => {




  return `/api/client/profile`
}

/**
 * @summary Update the current client's contact details
 */
export const updateClientProfile = async (profileUpdate: ProfileUpdate, options?: Parameters<typeof customFetch>[1]): Promise<Client> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return customFetch<Client>(getUpdateClientProfileUrl(),
  {
    ...options,
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(profileUpdate)
  }
);}





export const getUpdateClientProfileMutationKey = () => ['updateClientProfile'] as const;

export const getUpdateClientProfileMutationOptions = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof updateClientProfile>>, TError,UpdateClientProfileMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof updateClientProfile>>, TError,UpdateClientProfileMutationVariables, TContext> => {

const mutationKey = getUpdateClientProfileMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof updateClientProfile>>, UpdateClientProfileMutationVariables> = (props) => {
          const {data} = props ?? {};

          return  updateClientProfile(data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type UpdateClientProfileMutationResult = NonNullable<Awaited<ReturnType<typeof updateClientProfile>>>
    export type UpdateClientProfileMutationBody = BodyType<ProfileUpdate>
    export type UpdateClientProfileMutationError = ErrorType<unknown>
    export type UpdateClientProfileMutationVariables = {data: BodyType<ProfileUpdate>}

    /**
 * @summary Update the current client's contact details
 */
export const useUpdateClientProfile = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof updateClientProfile>>, TError,UpdateClientProfileMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof updateClientProfile>>,
        TError,
        UpdateClientProfileMutationVariables,
        TContext
      > => {
      return useMutation(getUpdateClientProfileMutationOptions(options));
    }

